package main

import "fmt"

func main() {
  x := 42
  y := 8

  // 加法
  res := x + y
  fmt.Println(res)

  // 减法
  res = x - y
  fmt.Println(res)

  // 乘法
  res = x * y
  fmt.Println(res)

  // 除法
  res = x / y
  fmt.Println(res)

  // 模运算(取余运算)
  res = x % y
  fmt.Println(res) 
}

